(function(root){
'use strict';
const X=root.MigrationExecution||(typeof require!=='undefined'?require('./execution.js'):null);
function build(s){
 const p=s.executionPlan,t=X.timeline(p,s.receipt,s.history,s.inspection,s.cleanup),observation=t.history.records.at(-1)||null,state=X.lifecycle(p,t.receipt,observation,t.inspection,t.cleanup),sections=[];
 const add=(id,title,scope,view,items,note)=>sections.push({id,title,scope,view,items,note,status:items.length?'Review required':'No recorded gaps; independent review remains'});
 const item=(resource,reason,owner='Platform / application owner',evidenceRef='')=>({resource,reason,owner,evidenceRef});
 add('scope','Confirm the handoff scope','Project','project',[
  ...(s.demo?[item('Source inventory','Illustrative demo; import an actual source snapshot before planning a real migration.')]:[]),
  ...(!s.hasTarget?[item('Target inventory','Import a target snapshot and verify collection coverage.')]:[]),
  ...(!s.pilotSelected?[item('Selected pilot','Choose an existing Deployment in the pilot builder.')]:[])
 ],'This handoff concerns one selected pilot. Inventory-wide findings remain separate.');
 add('execution','Resolve execution blockers','Selected pilot','pilot',p.blockers.map(r=>item(r.resource||p.workload,r.reason)),'Generated blockers are derived from current settings; they do not enumerate all runtime prerequisites.');
 add('prerequisites','Confirm prerequisites with owners','Selected pilot','pilot',p.prerequisites.map(r=>item(r.resource,r.action)),'Every generated prerequisite remains unverified by this app, including external state and recovery.');
 add('preflight','Review target preflight evidence','Selected pilot','target',s.preflight.rows.filter(r=>r.result?.status!=='Pass').map(r=>item(r.title,(r.result?.status||'NotRun')+': '+(r.result?.detail||'No passing scoped observation imported.'))),'Reported '+s.preflight.reportedPass+' of '+s.preflight.total+' target checks passed. Dry-run and presence checks do not prove application behavior.');
 add('runtime','Review the existing pilot run','Selected pilot','pilot',[
  ...(!t.receipt?[item(p.workload||'Pilot','No local run receipt imported.')]:t.receipt.mode==='validate'?[item(p.workload,'Validation report only; no deployment is established.')]:[]),
  ...(state.recoveryRequired?[item(t.runId,'Existing run needs observation/recovery review before further operations: '+state.status)]:[]),
  ...(t.receipt?.mode==='deploy'&&!state.recoveryRequired&&state.requiresPilotRun?[item(t.runId,state.status+': '+state.detail)]:[])
 ],state.status+'. '+state.detail+' Historical imports are not live health monitoring.');
 add('security','Review security controls and coverage','Inventory','security',[
  ...s.security.controls.filter(c=>c.status!=='Reported cases complete').map(c=>item(c.id,'Mapping '+(c.mappingComplete?'recorded':'incomplete')+'; scenarios '+(c.scenariosDefined?'defined':'incomplete')+'; distinct contexts '+(c.distinctContexts?'reported':'unresolved')+'. Source/target behavioral cases require review.','Security owner')),
  item('Security coverage','Review controls, exclusions and runtime enforcement beyond the collected inventory.','Security owner')
 ],'Reported '+s.security.reportedComplete+' of '+s.security.total+' observed controls have complete cases. Coverage is never established by object presence or an empty inventory.');
 add('acceptance','Review application acceptance','Selected pilot','acceptance',s.acceptance.rows.filter(r=>r.status!=='Reported source/target match').map(r=>item(r.title,(r.configured?'Definition recorded':'Definition incomplete')+'; source '+(r.source?.status||'NotRun')+'; target '+(r.target?.status||'NotRun')+'.',r.owner||'Application owner',[r.source?.evidenceRef,r.target?.evidenceRef].filter(Boolean).join(' · '))),'Reported '+s.acceptance.reportedComplete+' of '+s.acceptance.total+' source/target case matches. Owner reports require independent acceptance.');
 add('data','Review data and recovery','Inventory','storage',[
  ...s.storage.rows.map(r=>item(r.id,[r.status,...r.blockers,...r.missing.map(k=>'Missing '+k),...r.evidenceMissing.map(k=>'Missing '+k),...r.unknowns].join('; '),r.decision.owner||'Data / application owner')),
  ...s.storage.gaps.map(r=>item(r.resource,r.reason,'Data / application owner')),
  item('External state and writer ownership','Confirm external databases, consistency, writer fencing and a tested recovery/failback procedure even when no PVC is observed.','Data / application owner')
 ],'No data movement, consistency check or recovery rehearsal is performed by this app.');
 add('inventory','Review inventory-wide blockers','Inventory','findings',s.inventoryBlockers.map(r=>item(r.resource,r.title+': '+r.action)),'These findings remain open independently of the selected pilot and are not closed by draft mappings or local receipts.');
 add('approval','Record independent acceptance and authorization','Project','plan',[
  item('Application and security acceptance','Review actual behavior, effective controls, coverage and accountable owner acceptance.','Application / security owner'),
  item('Production change and recovery decision','Obtain external production-change authorization and confirm data recovery, routing, capacity and rollback/failback decisions.','Change / platform / data owner')
 ],'This review never grants approval or opens the production gate.');
 const next=state.recoveryRequired?{view:'pilot',action:'Review the existing pilot and recovery receipts',reason:state.status}:s.journey.next;
 return {schemaVersion:1,kind:'PilotHandoffReview',generatedAt:new Date().toISOString(),projectName:s.projectName,scope:{demo:s.demo,hasTarget:s.hasTarget,pilotSelected:s.pilotSelected,workload:p.workload,revision:p.planRevision,context:p.preflight.expectedContext,sourceClusterUID:p.preflight.sourceClusterUID,targetClusterUID:p.preflight.expectedClusterUID,runId:t.runId},next,lifecycle:state,observations:{runReportedAt:t.receipt?.observedAt||'',inspectionAt:t.inspection?.observedAt||'',cleanupAt:t.cleanup?.observedAt||'',retained:t.history.records.length,truncated:t.history.truncated,latestAt:observation?.observedAt||'',latestStatus:observation?.status||'',inspectionStatus:t.inspection?.status||'',cleanupStatus:t.cleanup?.status||''},evidenceDates:[{area:'Target preflight',times:s.preflight.rows.map(r=>r.result?.observedAt)},{area:'Security behavioral cases',times:(s.securityEvidence?.results||[]).map(r=>r.observedAt)},{area:'Application acceptance',times:s.acceptance.rows.flatMap(r=>[r.source?.observedAt,r.target?.observedAt])}].map(r=>{const times=r.times.filter(v=>Number.isFinite(Date.parse(v))).sort((a,b)=>Date.parse(a)-Date.parse(b));return {area:r.area,records:times.length,earliest:times[0]||'',latest:times.at(-1)||''};}),sections,artifacts:[{path:'project.vks-project.json',purpose:'Resume the saved workspace; findings and evidence are revalidated.'},{path:'pilot-execution/execution-plan.json',purpose:'Original bound plan for the local runner; preserve the matching original package.'},{path:'pilot-execution/pilot-timeline.json',purpose:'Retained observations and latest recovery records, when imported.'},{path:'acceptance/acceptance-workbook.md',purpose:'Owner-defined source/target behavior and evidence references.'}],productionReady:false,gate:'Closed',note:'Derived review of saved form settings and historical external observations. No commands execute, no evidence is authenticated, and no production cutover is authorized. Export the matching project and migration bundle for the receiving reviewer.'};
}
function checklist(r){
 const order=r.lifecycle.recoveryRequired?['runtime','scope','execution','prerequisites','preflight','security','acceptance','data','inventory','approval']:['scope','execution','prerequisites','preflight','runtime','security','acceptance','data','inventory','approval'];
 const stages=order.map(id=>{const section=r.sections.find(s=>s.id===id);if(!section)return null;let status=section.items.length?'Review required':'No recorded gaps';if(id==='runtime')status=r.lifecycle.status;else if(!section.items.length&&id==='scope')status='Scope recorded';else if(!section.items.length&&id==='execution')status='No generated blockers';else if(!section.items.length&&['preflight','acceptance'].includes(id))status='Reported evidence complete';return {...section,status,phase:section.view==='pilot'?(id==='runtime'?(r.lifecycle.recoveryRequired?'recover':r.lifecycle.requiresPilotRun?'run':'observe'):id==='execution'?'run':'prepare'):null,priority:r.lifecycle.recoveryRequired&&id==='runtime'?'Review existing run first':'',examples:section.items.slice(0,3)};}).filter(Boolean);
 return {schemaVersion:1,kind:'MigrationActionChecklist',generatedAt:r.generatedAt,projectName:r.projectName,scope:r.scope,next:r.next,stages,productionReady:false,gate:'Closed',note:'A derived navigation checklist, not a readiness score. Counts are scoped review items, not migration completion. Reported evidence and owner prerequisites require independent review.'};
}
const text=v=>String(v??'').replace(/[\r\n]+/g,' ').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/([\\|`*_\[\]#])/g,'\\$1');
function markdown(r){return '# Pilot handoff review\n\nProject: '+text(r.projectName)+'\n\nGenerated: '+text(r.generatedAt)+'\n\nProduction gate: Closed — independent acceptance required.\n\n## Scope\n\n'+Object.entries(r.scope).map(([k,v])=>'- '+text(k)+': '+text(v)).join('\n')+'\n\n## Next action\n\n'+text(r.next.action)+'\n\n'+text(r.next.reason)+'\n\n## Reported pilot state\n\n'+text(r.lifecycle.status)+'\n\n'+text(r.lifecycle.detail)+'\n\n'+'## Evidence dates\n\n'+r.evidenceDates.map(e=>'- '+text(e.area)+': '+e.records+' dated records; earliest '+text(e.earliest||'None')+'; latest '+text(e.latest||'None')).join('\n')+'\n\n'+r.sections.map(s=>'## '+text(s.title)+'\n\nScope: '+text(s.scope)+' · '+text(s.status)+'\n\n'+text(s.note)+'\n\n'+(s.items.length?'| Resource / case | Review required | Accountable reviewer | Evidence reference |\n| --- | --- | --- | --- |\n'+s.items.map(i=>'| '+[i.resource,i.reason,i.owner,i.evidenceRef].map(text).join(' | ')+' |').join('\n'):'No recorded gaps in this section. This does not establish readiness.')).join('\n\n')+'\n\n## Companion files\n\n'+r.artifacts.map(a=>'- '+text(a.path)+': '+text(a.purpose)).join('\n')+'\n\n'+text(r.note)+'\n';}
root.MigrationHandoff={build,markdown,checklist};if(typeof module!=='undefined')module.exports=root.MigrationHandoff;
})(typeof window!=='undefined'?window:globalThis);
